mapper.update:
{CALL
    DECLARE
        v_sql varchar2(500);
    BEGIN
        v_sql := 'CREATE INDEX ${tableName}_IDX1 ON ${tableName} (GROUP_KEY, SENDABLE)';
        execute immediate v_sql;

        v_sql := 'CREATE INDEX ${tableName}_IDX2 ON ${tableName} (STATUS, REQDATE, SENDABLE)';
        execute immediate v_sql;

        v_sql := 'CREATE INDEX ${tableName}_IDX3 ON ${tableName} (REQDATE)';
        execute immediate v_sql;
    END
}

UPDATE ${tableName}
SET
    STATUS = #{parameter.imageStatus}
    , SENDABLE = #{parameter.sendable}
    , IMG_ID = #{parameter.fileId}
    , RSLT = #{parameter.doneCode}
    , RSLTDESC = #{parameter.doneCodeDescription}
    , RPTDATE = TO_DATE(#{parameter.doneDate}, 'YYYYMMDDHH24MISS')
WHERE
    IMGKEY IS NULL
    IMGKEY = #{parameter.key}
